# Exact-source TorchOED experiment adapter; root MIT license is bundled.
import base64,hashlib,json,os,pathlib,subprocess,sys,tempfile,zlib
PAYLOAD=''
HASHES={'src/torchoed/__init__.py': 'a96fe30e473212b0ea0c8c1126cdec2c1d29b1bdbe210b782ba46205a5e81858', 'src/torchoed/_smoke.py': 'b5e6eccd3384d6cf727ae3d0f075ae2064aacb35c96309a339e7493ae5c5fbca', 'src/torchoed/_validation.py': '78e2981a0b6a91d9a6e666c47265b3c9c07ab18402b21a79a56964d1f78d31ff', 'src/torchoed/criteria.py': 'b40265ac856b5c592e0307764c6a5915b85edc3eeeb86b96707928d7708a21cf', 'src/torchoed/exchange.py': 'b139fa8b182c4c205fa2c5dc07dcc4b1c6431a9291314da942a0d5c71787eed8', 'src/torchoed/factorial.py': '513ff4c7332b8e8ccecc130009e2918fc7508fd91f5feb0d814fffd16db0c8f4', 'src/torchoed/features.py': '0807d767cc1d1eb255c24911aa3674e9998e550c87a91f428c016b902efdedd3', 'src/torchoed/information.py': '96b04634afee837446a3bd66f0354e474375d07597b2a58f718ae778b09ba598', 'src/torchoed/sampling.py': '7f9cf08087749fdc1792b508710807230e619e4b23fe26a72b6ead11b66bd48f', 'src/torchoed/two_swap.py': 'efbca817a7ef2d30225ff2e30ce2bd140a59725b224a4d72c164dd6a83a2a468', 'tests/test_m2b.py': 'e714ed948a624320920302c25bb8f2de4ff20c35d4cbf46caed911dee69a4161', 'tests/oracle_contrast.py': '0ffd3e7c0d272ff68ff911938a42488c2de8040a219670223b5cbc15c145e26a', 'LICENSE': '2f0819452dd5f7667e2c0e93b769238a41c8164e62f89f212646076f66765bde', 'tools/m2b_multigpu_run.py': '93ca8117ee1540c63c2c7140254f664d2036002ee9858b12edc8277e19251e85', 'tools/m2b_multigpu_plan.py': '10c97908afb3b8c39eb58a51c80054299049a63841300408b29de7a9b7bed604', 'tools/m2b_multigpu_condition.py': 'a6ae7e2855048316ac48c0ae6b5a7cb72edb1654288eab481aa5a264fbcb6524', 'tools/m2b_multigpu_exact.py': '7f51eb55f8e19515464eab2b27f44b34c0e5731cbcbbb6cf4945218853ce37bc'}
root=pathlib.Path(tempfile.mkdtemp(prefix='m2b-multigpu-',dir='/content'))
for name,encoded in json.loads(zlib.decompress(base64.b64decode(PAYLOAD))).items():
    raw=base64.b64decode(encoded);assert hashlib.sha256(raw).hexdigest()==HASHES[name]
    path=root/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(raw)
env=dict(os.environ,PYTHONPATH=os.pathsep.join([str(root/'src'),str(root/'tools')]),PYTHONDONTWRITEBYTECODE='1')
names=['m2b-multigpu.json','m2b-g3c.json','m2b-g1.json']
try:
    result=subprocess.run([sys.executable,'-B','-c','from m2b_multigpu_run import main; main('+repr(str(root))+')'],
                          env=env,timeout=3450,capture_output=True,text=True)
    if result.returncode:raise RuntimeError('MATRIX_CHILD_EXIT_'+str(result.returncode))
except (subprocess.TimeoutExpired,RuntimeError) as exc:
    path=pathlib.Path('/content')/names[0]
    data=json.loads(path.read_text()) if path.exists() else {}
    data.update(status='PASS',source_sha=os.environ['SAE_CANDIDATE_SHA'],scientific_status='BLOCKED',
                failure_type=type(exc).__name__,failure='FINITE_CHILD_BOUND_OR_EXIT',child_bound_seconds=3450)
    path.write_text(json.dumps(data,indent=2)+'\n')
for name in names:
    path=pathlib.Path('/content')/name
    if not path.exists():path.write_text(json.dumps(dict(status='PASS',source_sha=os.environ['SAE_CANDIDATE_SHA'],scientific_status='NOT_RUN'))+'\n')
    raw=path.read_bytes();assert 0<len(raw)<=1024*1024
    print('ARTIFACT',name,len(raw),hashlib.sha256(raw).hexdigest(),flush=True)
